CREATE FUNCTION agri.covariate_daily_features(p_cell_id uuid, p_window_start timestamp with time zone, p_window_end timestamp with time zone, p_as_of_time timestamp with time zone, p_schema_version character varying) RETURNS TABLE(cell_id uuid, observed_date date, feature_index integer, feature_name text, feature_kind text, feature_value double precision, input_count integer, expected_input_count integer, is_imputed boolean, source_release_count integer, data_available_at timestamp with time zone)
    LANGUAGE sql STABLE
    SET "TimeZone" TO 'UTC'
    SET "DateStyle" TO 'ISO, MDY'
    SET extra_float_digits TO '1'
    AS $$
    WITH spec AS (
        SELECT
            schema_entry.feature_index,
            schema_entry.feature_name,
            schema_entry.feature_kind,
            schema_entry.signal_name,
            schema_entry.lag_days,
            schema_entry.window_days
        FROM agri.covariate_feature_schema(p_schema_version) AS schema_entry
    ),
    lookback AS (
        SELECT agri.covariate_lookback_days(p_schema_version) AS lookback_days
    ),
    cell AS (
        SELECT spatial_cell.id
        FROM agri.spatial_cell AS spatial_cell
        WHERE spatial_cell.id = p_cell_id
    ),
    spine AS (
        -- CROSS JOIN cell: an unknown p_cell_id yields no days at all, rather than a grid of
        -- all-NULL features echoing the caller's own cell_id back as though it were real.
        SELECT (day_spine.bucket_start AT TIME ZONE 'UTC')::date AS observed_date
        FROM agri.forecast_date_spine(
            p_window_start,
            p_window_end + interval '1 day',
            interval '1 day'
        ) AS day_spine
        CROSS JOIN cell
    ),
    observation AS MATERIALIZED (
        -- One governed row per (signal, UTC day): the unique constraint includes
        -- source_release_id, so a re-ingest or revision yields several admissible rows for
        -- the same day. The latest-available release wins, ties broken deterministically,
        -- so a rolling window counts distinct days and can never double-count one.
        SELECT DISTINCT ON (signal.signal_name, (signal.observed_at AT TIME ZONE 'UTC')::date)
            signal.signal_name::text AS signal_name,
            (signal.observed_at AT TIME ZONE 'UTC')::date AS observed_date,
            signal.normalized_value,
            signal.is_observed,
            signal.source_release_id,
            signal.data_available_at
        FROM agri.signal_observation AS signal
        CROSS JOIN lookback
        WHERE signal.cell_id = p_cell_id
          AND signal.data_available_at <= p_as_of_time
          AND signal.support_key = 'surface'
          AND signal.quality_flag = 'accepted'
          AND signal.observed_at >= p_window_start - make_interval(days => lookback.lookback_days)
          AND signal.observed_at < p_window_end + interval '1 day'
        ORDER BY
            signal.signal_name,
            (signal.observed_at AT TIME ZONE 'UTC')::date,
            signal.data_available_at DESC,
            signal.observed_at DESC,
            signal.source_release_id DESC,
            signal.id DESC
    ),
    drought AS MATERIALIZED (
        SELECT
            drought_day.observed_date,
            drought_day.severity_class,
            drought_day.is_imputed,
            drought_day.source_release_id,
            drought_day.data_available_at
        FROM lookback
        CROSS JOIN LATERAL agri.drought_class_daily_series(
            p_cell_id,
            p_window_start - make_interval(days => lookback.lookback_days),
            p_window_end,
            p_as_of_time
        ) AS drought_day
    ),
    meteorology_feature AS (
        SELECT
            spine.observed_date,
            spec.feature_index,
            spec.feature_name,
            spec.feature_kind,
            CASE
                WHEN count(observation.normalized_value) = spec.window_days
                    THEN avg(observation.normalized_value)
            END AS feature_value,
            count(observation.normalized_value)::integer AS input_count,
            spec.window_days AS expected_input_count,
            coalesce(bool_or(NOT observation.is_observed), false) AS is_imputed,
            count(DISTINCT observation.source_release_id)::integer AS source_release_count,
            max(observation.data_available_at) AS data_available_at
        FROM spine
        CROSS JOIN spec
        LEFT JOIN observation
            ON observation.signal_name = spec.signal_name
           AND observation.observed_date
               BETWEEN spine.observed_date - spec.lag_days - spec.window_days + 1
                   AND spine.observed_date - spec.lag_days
        WHERE spec.feature_kind = 'meteorology'
        GROUP BY
            spine.observed_date,
            spec.feature_index,
            spec.feature_name,
            spec.feature_kind,
            spec.window_days
    ),
    drought_feature AS (
        SELECT
            spine.observed_date,
            spec.feature_index,
            spec.feature_name,
            spec.feature_kind,
            CASE
                WHEN spec.feature_name = 'drought_severity_imputed_lag_1'
                    THEN CASE WHEN drought.is_imputed THEN 1.0::double precision ELSE 0.0::double precision END
                ELSE drought.severity_class::double precision
            END AS feature_value,
            CASE
                WHEN spec.feature_name = 'drought_severity_imputed_lag_1'
                    THEN CASE WHEN drought.is_imputed IS NULL THEN 0 ELSE 1 END
                ELSE CASE WHEN drought.severity_class IS NULL THEN 0 ELSE 1 END
            END AS input_count,
            spec.window_days AS expected_input_count,
            coalesce(drought.is_imputed, false) AS is_imputed,
            CASE WHEN drought.source_release_id IS NULL THEN 0 ELSE 1 END AS source_release_count,
            drought.data_available_at
        FROM spine
        CROSS JOIN spec
        LEFT JOIN drought
            ON drought.observed_date = spine.observed_date - spec.lag_days
        WHERE spec.feature_kind = 'drought'
    ),
    calendar_feature AS (
        SELECT
            spine.observed_date,
            spec.feature_index,
            spec.feature_name,
            spec.feature_kind,
            CASE spec.feature_name
                WHEN 'day_of_year_sin'
                    THEN sin(2 * pi() * extract(doy FROM spine.observed_date)::double precision / 365.25)
                WHEN 'day_of_year_cos'
                    THEN cos(2 * pi() * extract(doy FROM spine.observed_date)::double precision / 365.25)
            END AS feature_value,
            spec.window_days AS input_count,
            spec.window_days AS expected_input_count,
            false AS is_imputed,
            0 AS source_release_count,
            NULL::timestamptz AS data_available_at
        FROM spine
        CROSS JOIN spec
        WHERE spec.feature_kind = 'calendar'
    ),
    combined AS (
        SELECT * FROM meteorology_feature
        UNION ALL
        SELECT * FROM drought_feature
        UNION ALL
        SELECT * FROM calendar_feature
    )
    SELECT
        p_cell_id,
        combined.observed_date,
        combined.feature_index,
        combined.feature_name::text,
        combined.feature_kind::text,
        combined.feature_value,
        combined.input_count,
        combined.expected_input_count,
        combined.is_imputed,
        combined.source_release_count,
        combined.data_available_at
    FROM combined
    ORDER BY combined.observed_date, combined.feature_index
$$;
